      : '<span style="font-size:9px;font-weight:800;letter-spacing:0.06em;padding:2px 6px;background:#dbeafe;color:#1e40af;border:1px solid #93c5fd;text-transform:uppercase;">' +
          d.options.length + ' choice' + (d.options.length === 1 ? '' : 's') +
        '</span>';
    var optionsHtml = d.isText
      ? '<div style="font-size:10px;color:#64748b;font-style:italic;">free-text input</div>'
      : '<div style="font-size:10px;color:#0f172a;line-height:1.5;">' +
          d.options.map(function (o, i) {
            var bg = i === 0 ? '#dcfce7' : (i === 1 ? '#fef3c7' : '#f1f5f9');
            var fg = i === 0 ? '#166534' : (i === 1 ? '#92400e' : '#475569');
            return '<span style="display:inline-block;background:' + bg + ';color:' + fg + ';padding:1px 6px;margin:1px 4px 1px 0;font-weight:600;font-size:10px;border-radius:0;">' + _esc(o) + '</span>';
          }).join("") +
        '</div>';
